package com.wizzadrds.theworldremembers.voice; import java.io.*; import java.nio.file.*; public final class LocalProcessTtsAdapter implements TtsAdapter{private final java.util.List<String> command;public LocalProcessTtsAdapter(java.util.List<String> command){if(command.isEmpty())throw new IllegalArgumentException();this.command=java.util.List.copyOf(command);}public Path synthesize(String text,VoiceProfile p,Path out) throws IOException,InterruptedException{var parent=out.toAbsolutePath().getParent();if(parent!=null)Files.createDirectories(parent);var a=new java.util.ArrayList<>(command);a.add(text);a.add(out.toString());a.add(p.language());a.add(p.modelId());a.add(Float.toString(p.rate()));a.add(Float.toString(p.pitch()));a.add(Float.toString(p.expressiveness()));var proc=new ProcessBuilder(a).redirectErrorStream(true).start();if(proc.waitFor()!=0)throw new IOException("Local TTS failed");return out;}}